const { existsSync, readFileSync } = await import('node:fs');
const pdfPath = process.env.PDF_PATH;
if (!pdfPath || !existsSync(pdfPath)) { throw new Error('PDF file not found at ' + pdfPath); }
globalThis.pdfBuffer = readFileSync(pdfPath);

const mod = await import('pdf-parse');
const PDFParse = mod.PDFParse || mod.default?.PDFParse || mod.default;
const parser = new PDFParse({ data: globalThis.pdfBuffer });
const result = await parser.getText();
await parser.destroy();
const lines = result.text.split(/\r?\n/).filter(l => l.trim().length > 0);
globalThis.heading = lines.length > 0 ? lines[0].trim() : '';
